import CoreServices
import Foundation

public enum PasteboardMarkers {
    public static let ownPrefix = AppIdentity.bundleIdentifier + "."
    public static let ownClipType = ownPrefix + "clip"
    public static let sourceType = "org.nspasteboard.source"

    public static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    public static func shouldSkip(types: some Sequence<String>) -> Bool {
        for type in types {
            if skipTypes.contains(type) || type.hasPrefix(ownPrefix) {
                return true
            }
            // NSPasteboardItem.types は UTI しか返さないため、空白を含む旧式の型名は
            // 動的 UTI (dyn.*) に化けて現れる。元の名前に戻して照合する
            if type.hasPrefix("dyn."), let legacy = legacyName(of: type), skipTypes.contains(legacy) {
                return true
            }
        }
        return false
    }

    public static func isMetadataType(_ type: String) -> Bool {
        type == sourceType || type.hasPrefix(ownPrefix)
    }

    static func legacyName(of dynamicType: String) -> String? {
        UTTypeCopyPreferredTagWithClass(dynamicType as CFString, kUTTagClassNSPboardType)?.takeRetainedValue() as String?
    }
}
